fn decode_shift(s: Vec<char>) -> Vec<char> {
    // We will shift each character 5 places to the left in the alphabet.
    // Since 'a'..'z' map to 0..25, we can do arithmetic in that range,
    // subtract 5 (via adding 21 = 26 - 5 to avoid negative wrap), then mod 26.
    let base = b'a';
    s.into_iter()
     .map(|c| {
         let c_u8 = c as u8;
         let idx = c_u8 - base;
         // shift left by 5: equivalent to idx - 5 mod 26
         let new_idx = (idx + 26 - 5) % 26;
         (base + new_idx) as char
     })
     .collect()
}

