    #[test]
    fn test_decode_shift_full() {
        // A round-trip: encode by shifting right 5, then decode
        let original = "rustaceanlang";
        let encoded: String = original
            .chars()
            .map(|c| {
                let base = b'a';
                let idx = c as u8 - base;
                let new_idx = (idx + 5) % 26;
                (base + new_idx) as char
            })
            .collect();
        let decoded: String = decode_shift(encoded.chars().collect()).into_iter().collect();
        assert_eq!(decoded, original);
    }

    #[test]
    fn test_decode_shift_wraparound() {
        let input: Vec<char> = "abcxyz".chars().collect();
        // a->v, b->w, c->x, x->s, y->t, z->u
        assert_eq!(
            decode_shift(input).into_iter().collect::<String>(),
            "vwxstu"
        );
    }
